create or replace function public.generate_vendor_accruals(p_year integer,p_month integer)returns integer language plpgsql security invoker set search_path=''as $$declare a record;period_start date:=make_date(p_year,p_month,1);period_end date:=(make_date(p_year,p_month,1)+interval'1 month - 1 day')::date;created_count integer:=0;begin if not public.has_permission('vendors.manage')then raise exception'insufficient_permission'using errcode='42501';end if;for a in select va.*,ps.project_id from public.vendor_assignments va join public.project_services ps on ps.id=va.project_service_id where va.status='active'and va.start_date<=period_end and(va.end_date is null or va.end_date>=period_start)loop insert into public.vendor_accruals(vendor_id,vendor_assignment_id,project_id,project_service_id,year,month,amount,currency,due_date,created_by)values(a.vendor_id,a.id,a.project_id,a.project_service_id,p_year,p_month,a.default_amount,a.currency,period_end,auth.uid())on conflict(vendor_assignment_id,year,month)do nothing;if found then created_count:=created_count+1;end if;end loop;update public.service_periods sp set cost_amount=coalesce((select sum(va.amount)from public.vendor_accruals va where va.project_service_id=sp.project_service_id and va.year=p_year and va.month=p_month and va.status<>'cancelled'),0)where sp.year=p_year and sp.month=p_month;return created_count;end$$;
create or replace function public.record_receivable_payment_to_account(p_receivable_id uuid,p_account_id uuid,p_amount numeric,p_payment_date date,p_notes text)returns uuid language plpgsql security invoker set search_path=''as $$declare rec public.receivables%rowtype;account_currency public.currency_code;paid numeric;new_payment uuid;new_status public.collection_status;begin if not(public.has_permission('collections.manage')or public.has_permission('finance.manage'))or not public.has_permission('accounts.manage')then raise exception'insufficient_permission'using errcode='42501';end if;select*into rec from public.receivables where id=p_receivable_id for update;if not found then raise exception'receivable_not_found';end if;select currency into account_currency from public.accounts where id=p_account_id and status='active';if account_currency is null or account_currency<>rec.currency then raise exception'currency_mismatch_or_account_missing';end if;select coalesce(sum(amount),0)into paid from public.payments where receivable_id=p_receivable_id;if p_amount<=0 or paid+p_amount>rec.total_amount then raise exception'invalid_payment_amount';end if;insert into public.payments(receivable_id,amount,currency,payment_date,account_id,notes,created_by)values(p_receivable_id,p_amount,rec.currency,p_payment_date,p_account_id,p_notes,auth.uid())returning id into new_payment;insert into public.finance_transactions(account_id,transaction_date,transaction_type,amount,currency,client_id,project_id,category,description,payment_id,created_by)values(p_account_id,p_payment_date,'income',p_amount,rec.currency,rec.client_id,rec.project_id,'Müşteri tahsilatı',p_notes,new_payment,auth.uid());paid:=paid+p_amount;new_status:=case when paid>=rec.total_amount then'paid'::public.collection_status else'partial'::public.collection_status end;update public.receivables set status=new_status where id=p_receivable_id;update public.service_periods set collection_status=new_status where id=rec.service_period_id;insert into public.collection_activities(receivable_id,activity_type,note,created_by)values(p_receivable_id,case when new_status='paid'then'completed'::public.collection_activity_type else'partial_payment'::public.collection_activity_type end,p_notes,auth.uid());return new_payment;end$$;
grant execute on function public.record_receivable_payment_to_account(uuid,uuid,numeric,date,text)to authenticated;
